cd /data; sqlite3 -header current.db "$(sed '/^select asg.period/,$d' /work/metrics.sql)
select asg.period, asg.route_id, r.route_key, p.pool_code, asg.release_id, asg.profile_id, count(*) ops, sum(lst.last_ok=0) term, round(100.0*sum(lst.last_ok=0)/count(*),2) term_pct, sum(att.n) attempts, sum(att.failed) failed, sum(att.n>1) retried
from asg join worker_pools p using(pool_id) join service_routes r using(route_id) join att using(operation_id) join lst using(operation_id) group by 1,2,3,4,5,6 order by 1,4,2;" ; sqlite3 -header current.db "
select f.code, count(*) from attempt_events a join failure_codes f using(code_id) join logical_operations o using(operation_id) where o.opened_at_ms>=1777719600000 and o.opened_at_ms<1777723200000 group by 1;
select count(*), sum(attempt_no) from attempt_events a join logical_operations o using(operation_id) where o.opened_at_ms>=1777719600000 and o.opened_at_ms<1777723200000;
select count(*) attempts_count_ops_by_attempt_no, attempt_no, sum(code_id=2) from attempt_events a join logical_operations o using(operation_id) where o.opened_at_ms>=1777719600000 and o.opened_at_ms<1777723200000 group by attempt_no;"

cd /data; cat > /work/ls9.sql <<'EOF'
with w as (select o.operation_id, o.opened_at_ms, case when o.opened_at_ms>=1778320800000 and o.opened_at_ms<1778324400000 then 'reference_10_11' when o.opened_at_ms>=1778324400000 and o.opened_at_ms<1778328000000 then 'incident_11_12' end period
 from logical_operations o join service_routes r using(route_id) join services s on s.service_id=r.service_id where s.service_code='ledger-sync' and o.opened_at_ms>=1778320800000 and o.opened_at_ms<1778328000000),
oc as (select w.period, w.opened_at_ms, e.operation_id, e.completed_at_ms, e.attempt_count, f.is_success, c.pool_id, c.cell_id from w join outcome_events e using(operation_id) join execution_cells c on c.cell_id=e.cell_id and w.opened_at_ms>=c.effective_from_ms and (c.effective_to_ms is null or w.opened_at_ms<c.effective_to_ms) join failure_codes f on f.code_id=e.final_code_id where w.period is not null)
select oc.period, p.pool_code, count(*) operations, sum(is_success=0) terminal_failures, round(100.0*sum(is_success=0)/count(*),4) terminal_failure_pct,
 sum(attempt_count>1) retried_operations, round(100.0*sum(attempt_count>1)/count(*),4) retry_pct, round(avg(completed_at_ms-opened_at_ms),4) mean_latency_ms
from oc join worker_pools p on p.pool_id=oc.pool_id group by oc.period, p.pool_code order by 1,2;
EOF
sqlite3 -header current.db < /work/ls9.sql
