select o.route_id, c.pool_id, count(*) from logical_operations o join outcome_events e using(operation_id) join execution_cells c using(cell_id) where o.route_id in (3,4,8) and o.opened_at_ms>=1778320800000 and o.opened_at_ms<1778328000000 group by 1,2;
select count(*) mismatch from logical_operations o join outcome_events e using(operation_id) join attempt_events a on a.operation_id=o.operation_id and a.attempt_no=e.attempt_count join failure_codes f on f.code_id=a.code_id join failure_codes g on g.code_id=e.final_code_id where o.opened_at_ms>=1778320800000 and o.opened_at_ms<1778328000000 and a.code_id<>e.final_code_id;
